package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.compile;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;
/** Independent immutable executable resource ClassOperation. */
public final class CompiledClassOperation{private final StableId id,sourceComponentId;private final String displayName;private final CompiledSkill.Trigger activation;private final CompiledSkill.Condition condition;private final CompiledSkill.Cost cost;private final int actionTimeTurns;private final CompiledSkill.ResourceOperation operation;private final boolean hudVisible;private final int hudOrder;public CompiledClassOperation(StableId id,String name,StableId source,CompiledSkill.Trigger activation,CompiledSkill.Condition condition,CompiledSkill.Cost cost,int turns,CompiledSkill.ResourceOperation operation,boolean visible,int order){if(id==null||name==null||activation==null||condition==null||cost==null||operation==null||turns<1||order<0)throw new IllegalArgumentException("invalid compiled class operation");this.id=id;displayName=name;sourceComponentId=source;this.activation=activation;this.condition=condition;this.cost=cost;actionTimeTurns=turns;this.operation=operation;hudVisible=visible;hudOrder=order;}public StableId id(){return id;}public String displayName(){return displayName;}public StableId sourceComponentId(){return sourceComponentId;}public CompiledSkill.Trigger activation(){return activation;}public CompiledSkill.Condition condition(){return condition;}public CompiledSkill.Cost cost(){return cost;}public int actionTimeTurns(){return actionTimeTurns;}public CompiledSkill.ResourceOperation operation(){return operation;}public boolean hudVisible(){return hudVisible;}public int hudOrder(){return hudOrder;}}
